import random
from typing import Dict, List, Any, Optional, Tuple
from dataclasses import dataclass, field
from enum import Enum, auto

class OpticalChannelState(Enum):
    ACTIVE = auto()
    IDLE = auto()
    FAILED = auto()

@dataclass
class OpticalChannel:
    channel_id: uuid.UUID
    source_chip_id: uuid.UUID
    target_chip_id: uuid.UUID
    bandwidth_gbps: float
    latency_ps: int
    state: OpticalChannelState
    error_rate: float

@dataclass
class CoolingLoop:
    loop_id: uuid.UUID
    flow_rate_lpm: float
    inlet_temp_celsius: float
    outlet_temp_celsius: float
    pressure_psi: float

class RackFramework:
    def __init__(self, rack_id: uuid.UUID, chip_capacity: int = 256):
        self.rack_id = rack_id
        self.chip_capacity = chip_capacity
        self.installed_chips: Dict[uuid.UUID, Any] = {}
        self.optical_mesh: Dict[uuid.UUID, OpticalChannel] = {}
        self.cooling_system: CoolingLoop = CoolingLoop(
            loop_id=uuid.uuid4(),
            flow_rate_lpm=50.0,
            inlet_temp_celsius=20.0,
            outlet_temp_celsius=25.0,
            pressure_psi=15.0
        )
        self.ambient_temp_celsius = 22.0
        self.total_power_draw_watts = 0.0
        self.total_heat_dissipation_watts = 0.0

    def install_chip(self, chip: Any, slot_position: int):
        if len(self.installed_chips) >= self.chip_capacity:
            raise OverflowError("Rack is at full capacity.")
        if chip.chip_id in self.installed_chips:
            raise ValueError("Chip already installed in this rack.")
        self.installed_chips[chip.chip_id] = {"chip": chip, "slot": slot_position}
        self.total_power_draw_watts += 300
        self.total_heat_dissipation_watts += 280

    def remove_chip(self, chip_id: uuid.UUID):
        if chip_id in self.installed_chips:
            del self.installed_chips[chip_id]
            self.total_power_draw_watts -= 300
            self.total_heat_dissipation_watts -= 280

    def establish_optical_link(self, source_chip_id: uuid.UUID, target_chip_id: uuid.UUID) -> uuid.UUID:
        if source_chip_id not in self.installed_chips or target_chip_id not in self.installed_chips:
            raise ValueError("One or both chips not installed in the rack.")
        if source_chip_id == target_chip_id:
            raise ValueError("Cannot link a chip to itself.")

        existing_link = next((ch for ch in self.optical_mesh.values() if ch.source_chip_id == source_chip_id and ch.target_chip_id == target_chip_id), None)
        if existing_link:
            return existing_link.channel_id

        channel_id = uuid.uuid4()
        new_channel = OpticalChannel(
            channel_id=channel_id,
            source_chip_id=source_chip_id,
            target_chip_id=target_chip_id,
            bandwidth_gbps=100.0,
            latency_ps=random.randint(500, 2000),
            state=OpticalChannelState.ACTIVE,
            error_rate=random.uniform(1e-12, 1e-15)
        )
        self.optical_mesh[channel_id] = new_channel
        return channel_id

    def transmit_data(self, source_chip_id: uuid.UUID, target_chip_id: uuid.UUID, data_packet: bytes) -> bool:
        channel = next((ch for ch in self.optical_mesh.values() if ch.source_chip_id == source_chip_id and ch.target_chip_id == target_chip_id), None)
        if not channel or channel.state != OpticalChannelState.ACTIVE:
            return False
        if random.random() < channel.error_rate * len(data_packet):
            return False
        return True

    def update_thermal_state(self):
        total_chip_heat = sum(chip["chip"].temperature_celsius for chip in self.installed_chips.values()) if self.installed_chips else 0
        avg_chip_temp = total_chip_heat / len(self.installed_chips) if self.installed_chips else self.ambient_temp_celsius

        heat_load_factor = self.total_heat_dissipation_watts / (self.chip_capacity * 280)
        self.cooling_system.outlet_temp_celsius = self.cooling_system.inlet_temp_celsius + 10.0 * heat_load_factor

        for chip_data in self.installed_chips.values():
            chip = chip_data["chip"]
            ambient_for_chip = self.cooling_system.outlet_temp_celsius
            workload = 1.0 if chip.get_chip_status()["active_cores"] > 0 else 0.1
            chip.update_temperature(ambient_for_chip, workload)

    def get_rack_status(self) -> Dict[str, Any]:
        active_channels = sum(1 for ch in self.optical_mesh.values() if ch.state == OpticalChannelState.ACTIVE)
        return {
            "rack_id": str(self.rack_id),
            "chip_capacity": self.chip_capacity,
            "installed_chips": len(self.installed_chips),
            "active_optical_channels": active_channels,
            "total_power_draw_watts": self.total_power_draw_watts,
            "total_heat_dissipation_watts": self.total_heat_dissipation_watts,
            "cooling_inlet_temp_celsius": self.cooling_system.inlet_temp_celsius,
            "cooling_outlet_temp_celsius": self.cooling_system.outlet_temp_celsius,
            "cooling_flow_rate_lpm": self.cooling_system.flow_rate_lpm
        }

    def run_diagnostics(self) -> Dict[str, Any]:
        failed_chips = [cid for cid, data in self.installed_chips.items() if data["chip"].temperature_celsius > 100.0]
        failed_channels = [str(ch.channel_id) for ch in self.optical_mesh.values() if ch.state == OpticalChannelState.FAILED]
        return {
            "failed_chips": [str(cid) for cid in failed_chips],
            "failed_optical_channels": failed_channels,
            "cooling_pressure_psi": self.cooling_system.pressure_psi
        }
