import uuid
import time
import random
from typing import Dict, List, Any, Optional
from dataclasses import dataclass, field
from enum import Enum, auto

class FabricationStage(Enum):
    DESIGN_RECEIVED = auto()
    MASK_GENERATION = auto()
    WAFER_START = auto()
    PHOTOLITHOGRAPHY = auto()
    ETCHING = auto()
    DEPOSITION = auto()
    CHEMICAL_MECHANICAL_POLISHING = auto()
    METALLIZATION = auto()
    WAFER_TEST = auto()
    DICE = auto()
    PACKAGING = auto()
    FINAL_TEST = auto()
    SHIPPED = auto()
    FAILED = auto()

@dataclass
class WaferLot:
    lot_id: uuid.UUID
    design_id: uuid.UUID
    quantity: int
    current_stage: FabricationStage
    start_time: float
    completion_time: Optional[float] = None
    yield_rate: float = 0.0
    notes: List[str] = field(default_factory=list)

class TSMCFabricationSimulator:
    def __init__(self, process_node_nm: int = 7):
        self.process_node_nm = process_node_nm
        self.active_lots: Dict[uuid.UUID, WaferLot] = {}
        self.completed_lots: Dict[uuid.UUID, WaferLot] = {}
        self.stage_durations_days = {
            FabricationStage.DESIGN_RECEIVED: 1,
            FabricationStage.MASK_GENERATION: 14,
            FabricationStage.WAFER_START: 1,
            FabricationStage.PHOTOLITHOGRAPHY: 20,
            FabricationStage.ETCHING: 15,
            FabricationStage.DEPOSITION: 10,
            FabricationStage.CHEMICAL_MECHANICAL_POLISHING: 8,
            FabricationStage.METALLIZATION: 12,
            FabricationStage.WAFER_TEST: 5,
            FabricationStage.DICE: 2,
            FabricationStage.PACKAGING: 3,
            FabricationStage.FINAL_TEST: 4,
            FabricationStage.SHIPPED: 1,
        }
        self.base_yield = 0.55

    def submit_lot_for_fabrication(self, design_id: uuid.UUID, quantity: int) -> uuid.UUID:
        lot_id = uuid.uuid4()
        new_lot = WaferLot(
            lot_id=lot_id,
            design_id=design_id,
            quantity=quantity,
            current_stage=FabricationStage.DESIGN_RECEIVED,
            start_time=time.time()
        )
        self.active_lots[lot_id] = new_lot
        return lot_id

    def advance_fabrication_process(self, lot_id: uuid.UUID) -> bool:
        if lot_id not in self.active_lots:
            return False
        lot = self.active_lots[lot_id]
        current_stage = lot.current_stage

        if current_stage == FabricationStage.SHIPPED or current_stage == FabricationStage.FAILED:
            return False

        stages = list(FabricationStage)
        current_index = stages.index(current_stage)
        next_stage = stages[current_index + 1]

        lot.current_stage = next_stage
        lot.notes.append(f"Advanced to {next_stage.name} at {time.time()}")

        if next_stage == FabricationStage.WAFER_TEST:
            self._calculate_yield(lot)
            if lot.yield_rate < 0.1:
                lot.current_stage = FabricationStage.FAILED
                lot.notes.append("Lot failed due to critically low yield.")
                self._finalize_lot(lot)
                return True

        if next_stage == FabricationStage.SHIPPED:
            self._finalize_lot(lot)

        return True

    def _calculate_yield(self, lot: WaferLot):
        defect_density = random.uniform(0.1, 1.5)
        die_area_mm2 = 100
        yield_factor = math.exp(-defect_density * die_area_mm2)
        process_variation = random.uniform(0.9, 1.1)
        lot.yield_rate = self.base_yield * yield_factor * process_variation
        lot.yield_rate = max(0.0, min(1.0, lot.yield_rate))
        lot.notes.append(f"Yield calculated: {lot.yield_rate:.2%}")

    def _finalize_lot(self, lot: WaferLot):
        lot.completion_time = time.time()
        self.completed_lots[lot.lot_id] = lot
        if lot.lot_id in self.active_lots:
            del self.active_lots[lot.lot_id]

    def get_lot_status(self, lot_id: uuid.UUID) -> Optional[Dict[str, Any]]:
        lot = self.active_lots.get(lot_id) or self.completed_lots.get(lot_id)
        if not lot:
            return None
        return {
            "lot_id": str(lot.lot_id),
            "design_id": str(lot.design_id),
            "quantity": lot.quantity,
            "current_stage": lot.current_stage.name,
            "start_time": lot.start_time,
            "completion_time": lot.completion_time,
            "yield_rate": lot.yield_rate,
            "notes": lot.notes
        }

    def run_full_fabrication_cycle(self, lot_id: uuid.UUID) -> Dict[str, Any]:
        if lot_id not in self.active_lots:
            return {"error": "Lot not found or already completed."}

        lot = self.active_lots[lot_id]
        while lot.current_stage not in [FabricationStage.SHIPPED, FabricationStage.FAILED]:
            self.advance_fabrication_process(lot_id)
            time.sleep(0.01)

        return self.get_lot_status(lot_id)

    def get_shipped_chips(self, lot_id: uuid.UUID) -> List[uuid.UUID]:
        lot = self.completed_lots.get(lot_id)
        if not lot or lot.current_stage != FabricationStage.SHIPPED:
            return []

        num_good_chips = int(lot.quantity * 25 * lot.yield_rate)
        return [uuid.uuid4() for _ in range(num_good_chips)]
