    pub fn init(allocator: Allocator, chip_id: [16]u8, core_count: usize) !NeuromorphicChip7nm {
        if (core_count != 1024) {
            return error.InvalidCoreCount;
        }

        var chip = NeuromorphicChip7nm{
            .allocator = allocator,
            .chip_id = chip_id,
            .cores = AutoHashMap([16]u8, NeuronCore).init(allocator),
            .global_event_bus = ArrayList(struct { event: axiom_system.CausalEvent, targets: ArrayList([16]u8) }).init(allocator),
            .entropy_pool = ArrayList(f64).init(allocator),
            .power_state = true,
            .temperature_celsius = 45.0,
        };

        try chip.initializeCores(core_count);
        try chip.initializeInterconnect();

        return chip;
    }

    pub fn deinit(self: *NeuromorphicChip7nm) void {
        var core_it = self.cores.valueIterator();
        while (core_it.next()) |core| {
            core.deinit();
        }
        self.cores.deinit();

        for (self.global_event_bus.items) |*item| {
            item.targets.deinit();
        }
        self.global_event_bus.deinit();

        self.entropy_pool.deinit();
    }

    fn initializeCores(self: *NeuromorphicChip7nm, count: usize) !void {
        var prng = std.rand.DefaultPrng.init(blk: {
            var seed: u64 = undefined;
            std.os.getrandom(std.mem.asBytes(&seed)) catch 0;
            break :blk seed;
        });

        var i: usize = 0;
        while (i < count) : (i += 1) {
            var core_id: [16]u8 = undefined;
            prng.random().bytes(&core_id);

            const new_core = try NeuronCore.init(self.allocator, core_id);
            try self.cores.put(core_id, new_core);
        }
    }

    fn initializeInterconnect(self: *NeuromorphicChip7nm) !void {
        var prng = std.rand.DefaultPrng.init(blk: {
            var seed: u64 = undefined;
            std.os.getrandom(std.mem.asBytes(&seed)) catch 0;
            break :blk seed;
        });

        var core_ids = ArrayList([16]u8).init(self.allocator);
        defer core_ids.deinit();

        var core_it = self.cores.keyIterator();
        while (core_it.next()) |core_id| {
            try core_ids.append(core_id.*);
        }

        for (core_ids.items) |core_id| {
            const num_connections = prng.random().intRangeAtMost(usize, 8, 32);
            var core_ptr = self.cores.getPtr(core_id).?;

            var conn_idx: usize = 0;
            while (conn_idx < num_connections and conn_idx < core_ids.items.len - 1) : (conn_idx += 1) {
                const random_idx = prng.random().intRangeLessThan(usize, 0, core_ids.items.len);
                const target_core_id = core_ids.items[random_idx];

                if (!std.mem.eql(u8, &core_id, &target_core_id)) {
                    const weight = prng.random().float(f64) * 2.0 - 1.0;
                    const delay = prng.random().intRangeAtMost(i32, 50, 500);

                    try core_ptr.synaptic_weights.append(SynapticWeight{
                        .target_core_id = target_core_id,
                        .weight = weight,
                        .delay_ps = delay,
                    });
                }
