        }
    }

    pub fn injectCausalEvent(self: *NeuromorphicChip7nm, event: axiom_system.CausalEvent, target_core_ids: ?ArrayList([16]u8)) !void {
        if (!self.power_state) {
            return;
        }

        var prng = std.rand.DefaultPrng.init(blk: {
            var seed: u64 = undefined;
            std.os.getrandom(std.mem.asBytes(&seed)) catch 0;
            break :blk seed;
        });

        var targets = ArrayList([16]u8).init(self.allocator);
        defer if (target_core_ids == null) targets.deinit();

        if (target_core_ids) |tids| {
            for (tids.items) |tid| {
                try targets.append(tid);
            }
        } else {
            var core_ids = ArrayList([16]u8).init(self.allocator);
            defer core_ids.deinit();

            var core_it = self.cores.keyIterator();
            while (core_it.next()) |core_id| {
                try core_ids.append(core_id.*);
            }

            const num_targets = prng.random().intRangeAtMost(usize, 1, 4);
            var i: usize = 0;
            while (i < num_targets and i < core_ids.items.len) : (i += 1) {
                const idx = prng.random().intRangeLessThan(usize, 0, core_ids.items.len);
                try targets.append(core_ids.items[idx]);
            }
        }

        for (targets.items) |core_id| {
            if (self.cores.getPtr(core_id)) |core_ptr| {
                try core_ptr.processing_queue.append(event);
                core_ptr.state = .processing;
            }
        }
    }

    pub fn processEvents(self: *NeuromorphicChip7nm, current_time_ns: i64) !void {
        if (!self.power_state) {
            return;
        }

        var core_it = self.cores.valueIterator();
        while (core_it.next()) |core_ptr| {
            if (core_ptr.state == .processing and core_ptr.processing_queue.items.len > 0) {
                const event = core_ptr.processing_queue.orderedRemove(0);
                try self.executeCausalOperation(core_ptr, event, current_time_ns);

                if (core_ptr.processing_queue.items.len == 0) {
                    core_ptr.state = .idle;
                }
            }
        }
    }

    fn executeCausalOperation(self: *NeuromorphicChip7nm, core: *NeuronCore, event: axiom_system.CausalEvent, current_time_ns: i64) !void {
        core.last_event_timestamp = current_time_ns;

        const current_activation = core.local_memory.get(event.concept.identifier) orelse 0.0;
        const new_activation = current_activation + 1.0;
        try core.local_memory.put(event.concept.identifier, new_activation);

        if (new_activation > 1.5) {
            try self.propagateSpike(core, event, current_time_ns);
        }

        var ctx_it = event.context.iterator();
        while (ctx_it.next()) |entry| {
            var prng = std.rand.DefaultPrng.init(blk: {
                var seed: u64 = undefined;
                std.os.getrandom(std.mem.asBytes(&seed)) catch 0;
                break :blk seed;
            });
            var memory_key: [16]u8 = undefined;
            prng.random().bytes(&memory_key);

            const value = std.fmt.parseFloat(f64, entry.value_ptr.*) catch 0.0;
            try core.local_memory.put(memory_key, value);
        }
