    fn propagateSpike(self: *NeuromorphicChip7nm, source_core: *NeuronCore, original_event: axiom_system.CausalEvent, current_time_ns: i64) !void {
        for (source_core.synaptic_weights.items) |weight| {
            if (self.cores.getPtr(weight.target_core_id)) |target_core| {
                if (weight.weight > 0.5) {
                    var prng = std.rand.DefaultPrng.init(blk: {
                        var seed: u64 = undefined;
