    pub fn updateTemperature(self: *NeuromorphicChip7nm, ambient_temp_celsius: f64, workload_factor: f64) !void {
        var active_cores: usize = 0;
        var core_it = self.cores.valueIterator();
        while (core_it.next()) |core| {
            if (core.state != .idle) {
                active_cores += 1;
