    fn emergencyThrottle(self: *NeuromorphicChip7nm) void {
        var core_it = self.cores.valueIterator();
        while (core_it.next()) |core_ptr| {
            if (core_ptr.state == .processing) {
                const half_len = core_ptr.processing_queue.items.len / 2;
                var new_queue = ArrayList(axiom_system.CausalEvent).init(self.allocator);
                var i: usize = 0;
                while (i < half_len and i < core_ptr.processing_queue.items.len) : (i += 1) {
                    new_queue.append(core_ptr.processing_queue.items[i]) catch {};
                }
                core_ptr.processing_queue.deinit();
                core_ptr.processing_queue = new_queue;
