const std = @import("std");
const Allocator = std.mem.Allocator;
const ArrayList = std.ArrayList;
const StringHashMap = std.StringHashMap;

pub const HDLTokenType = enum {
    identifier,
    keyword,
    number,
    operator,
    delimiter,
    comment,
    newline,
};

pub const HDLToken = struct {
    token_type: HDLTokenType,
    value: []const u8,
    line: usize,
    column: usize,
};

pub const CausalHDLCompiler = struct {
    allocator: Allocator,
    keywords: ArrayList([]const u8),
    operators: ArrayList([]const u8),
    delimiters: ArrayList([]const u8),
    ast_root: ?StringHashMap(ArrayList(StringHashMap([]const u8))),
    symbol_table: StringHashMap(StringHashMap([]const u8)),

    pub fn init(allocator: Allocator) !CausalHDLCompiler {
        var compiler = CausalHDLCompiler{
            .allocator = allocator,
            .keywords = ArrayList([]const u8).init(allocator),
            .operators = ArrayList([]const u8).init(allocator),
            .delimiters = ArrayList([]const u8).init(allocator),
            .ast_root = null,
            .symbol_table = StringHashMap(StringHashMap([]const u8)).init(allocator),
        };

        try compiler.keywords.append("MODULE");
        try compiler.keywords.append("ENDMODULE");
        try compiler.keywords.append("INPUT");
        try compiler.keywords.append("OUTPUT");
        try compiler.keywords.append("WIRE");
        try compiler.keywords.append("REG");
        try compiler.keywords.append("CAUSAL_EVENT");
        try compiler.keywords.append("ABSTRACT_CONCEPT");
        try compiler.keywords.append("SYNAPSE");
        try compiler.keywords.append("NEURON_CORE");
        try compiler.keywords.append("CHIP");
        try compiler.keywords.append("ASYNC");
        try compiler.keywords.append("ON");
        try compiler.keywords.append("SPIKE");
        try compiler.keywords.append("PROCESS");
        try compiler.keywords.append("LINK");
        try compiler.keywords.append("STRENGTH");
        try compiler.keywords.append("DELAY");
        try compiler.keywords.append("PARAMETER");
        try compiler.keywords.append("LOCAL_MEMORY");
        try compiler.keywords.append("PROPAGATE");

        try compiler.operators.append("=");
        try compiler.operators.append("<");
        try compiler.operators.append(">");
        try compiler.operators.append("<=");
        try compiler.operators.append(">=");
        try compiler.operators.append("==");
        try compiler.operators.append("!=");
        try compiler.operators.append("+");
        try compiler.operators.append("-");
        try compiler.operators.append("*");
        try compiler.operators.append("/");

        try compiler.delimiters.append("(");
        try compiler.delimiters.append(")");
        try compiler.delimiters.append("[");
        try compiler.delimiters.append("]");
        try compiler.delimiters.append("{");
        try compiler.delimiters.append("}");
        try compiler.delimiters.append(";");
        try compiler.delimiters.append(",");

        return compiler;
    }

    pub fn deinit(self: *CausalHDLCompiler) void {
        self.keywords.deinit();
        self.operators.deinit();
        self.delimiters.deinit();

        if (self.ast_root) |*root| {
            var it = root.valueIterator();
            while (it.next()) |list| {
                for (list.items) |*item| {
                    item.deinit();
                }
                list.deinit();
            }
            root.deinit();
        }

        var sym_it = self.symbol_table.valueIterator();
        while (sym_it.next()) |item| {
            item.deinit();
        }
        self.symbol_table.deinit();
    }

    pub fn tokenize(self: *CausalHDLCompiler, code: []const u8) !ArrayList(HDLToken) {
        var tokens = ArrayList(HDLToken).init(self.allocator);
        var line: usize = 1;
        var column: usize = 1;
        var i: usize = 0;

        while (i < code.len) {
            const ch = code[i];

            if (ch == '\n') {
                try tokens.append(HDLToken{
                    .token_type = .newline,
                    .value = "\n",
                    .line = line,
                    .column = column,
                });
                line += 1;
                column = 1;
                i += 1;
                continue;
            }

            if (std.ascii.isWhitespace(ch)) {
                i += 1;
                column += 1;
                continue;
            }

            if (ch == '/' and i + 1 < code.len and code[i + 1] == '/') {
                const start = i;
                while (i < code.len and code[i] != '\n') {
                    i += 1;
                }
                try tokens.append(HDLToken{
                    .token_type = .comment,
                    .value = code[start..i],
                    .line = line,
                    .column = column,
                });
                continue;
            }

            if (std.ascii.isDigit(ch)) {
                const start = i;
                const start_col = column;
                while (i < code.len and (std.ascii.isDigit(code[i]) or code[i] == '.')) {
                    i += 1;
                    column += 1;
                }
                try tokens.append(HDLToken{
                    .token_type = .number,
                    .value = code[start..i],
                    .line = line,
                    .column = start_col,
                });
                continue;
            }

            if (std.ascii.isAlphabetic(ch) or ch == '_') {
                const start = i;
                const start_col = column;
                while (i < code.len and (std.ascii.isAlphanumeric(code[i]) or code[i] == '_')) {
                    i += 1;
                    column += 1;
                }
                const word = code[start..i];

                var is_keyword = false;
                for (self.keywords.items) |kw| {
                    if (std.mem.eql(u8, word, kw)) {
                        is_keyword = true;
                        break;
                    }
                }

                try tokens.append(HDLToken{
                    .token_type = if (is_keyword) .keyword else .identifier,
                    .value = word,
                    .line = line,
                    .column = start_col,
                });
                continue;
            }

            var matched_operator = false;
            for (self.operators.items) |op| {
                if (i + op.len <= code.len and std.mem.eql(u8, code[i..i + op.len], op)) {
                    try tokens.append(HDLToken{
                        .token_type = .operator,
                        .value = op,
                        .line = line,
                        .column = column,
                    });
                    i += op.len;
                    column += op.len;
                    matched_operator = true;
                    break;
                }
            }
            if (matched_operator) continue;

            var matched_delimiter = false;
            for (self.delimiters.items) |delim| {
                if (i + delim.len <= code.len and std.mem.eql(u8, code[i..i + delim.len], delim)) {
                    try tokens.append(HDLToken{
                        .token_type = .delimiter,
                        .value = delim,
                        .line = line,
                        .column = column,
                    });
                    i += delim.len;
                    column += delim.len;
                    matched_delimiter = true;
                    break;
                }
            }
            if (matched_delimiter) continue;

            i += 1;
            column += 1;
        }

        return tokens;
    }

    pub fn parse(self: *CausalHDLCompiler, tokens: ArrayList(HDLToken)) !StringHashMap(ArrayList(StringHashMap([]const u8))) {
        var ast = StringHashMap(ArrayList(StringHashMap([]const u8))).init(self.allocator);
        var modules = ArrayList(StringHashMap([]const u8)).init(self.allocator);
        try ast.put("modules", modules);

        var i: usize = 0;
        while (i < tokens.items.len) {
            const token = tokens.items[i];
            if (token.token_type == .keyword and std.mem.eql(u8, token.value, "MODULE")) {
                const result = try self.parseModule(tokens, i);
                i = result.next_index;
                if (result.module_node) |mod_node| {
                    try modules.append(mod_node);
                }
            } else {
                i += 1;
            }
        }

        self.ast_root = ast;
        return ast;
    }

    const ParseModuleResult = struct {
        next_index: usize,
        module_node: ?StringHashMap([]const u8),
    };

    fn parseModule(self: *CausalHDLCompiler, tokens: ArrayList(HDLToken), index: usize) !ParseModuleResult {
        var i = index + 1;
        if (i >= tokens.items.len or tokens.items[i].token_type != .identifier) {
            return ParseModuleResult{ .next_index = i, .module_node = null };
        }

        const module_name = tokens.items[i].value;
        var module_node = StringHashMap([]const u8).init(self.allocator);
        try module_node.put("type", "module");
        try module_node.put("name", module_name);

        i += 1;
        while (i < tokens.items.len) {
            const token = tokens.items[i];
            if (token.token_type == .keyword and std.mem.eql(u8, token.value, "ENDMODULE")) {
                return ParseModuleResult{ .next_index = i + 1, .module_node = module_node };
            }
            i += 1;
        }

        return ParseModuleResult{ .next_index = i, .module_node = null };
    }

    pub fn generateNetlist(self: *CausalHDLCompiler, ast: StringHashMap(ArrayList(StringHashMap([]const u8)))) !ArrayList(u8) {
        var netlist = ArrayList(u8).init(self.allocator);
        const writer = netlist.writer();

        if (ast.get("modules")) |modules| {
            for (modules.items) |module| {
                if (module.get("name")) |name| {
                    try writer.print("MODULE {s}\n", .{name});
                    try writer.print("ENDMODULE\n", .{});
                }
            }
        }

        return netlist;
    }

    pub fn compileHdlCode(self: *CausalHDLCompiler, code: []const u8) !ArrayList(u8) {
        const tokens = try self.tokenize(code);
        defer tokens.deinit();

        const ast = try self.parse(tokens);
        const netlist = try self.generateNetlist(ast);

        return netlist;
    }
};
