### fabrication_simulator.zig

```zig
const std = @import("std");
const Allocator = std.mem.Allocator;
const ArrayList = std.ArrayList;
const AutoHashMap = std.AutoHashMap;

pub const FabricationStage = enum {
    design_received,
    mask_generation,
    wafer_start,
    photolithography,
    etching,
    deposition,
    chemical_mechanical_polishing,
    metallization,
    wafer_test,
    dice,
    packaging,
    final_test,
    shipped,
    failed,
};

pub const WaferLot = struct {
    lot_id: [16]u8,
    design_id: [16]u8,
    quantity: i32,
    current_stage: FabricationStage,
    start_time: f64,
    completion_time: ?f64,
    yield_rate: f64,
    notes: ArrayList([]const u8),

    pub fn init(allocator: Allocator, lot_id: [16]u8, design_id: [16]u8, quantity: i32, start_time: f64) !WaferLot {
        return WaferLot{
            .lot_id = lot_id,
            .design_id = design_id,
            .quantity = quantity,
            .current_stage = .design_received,
            .start_time = start_time,
            .completion_time = null,
            .yield_rate = 0.0,
            .notes = ArrayList([]const u8).init(allocator),
        };
    }

    pub fn deinit(self: *WaferLot) void {
        self.notes.deinit();
    }
};

pub const TSMCFabricationSimulator = struct {
    allocator: Allocator,
    process_node_nm: i32,
    active_lots: AutoHashMap([16]u8, WaferLot),
    completed_lots: AutoHashMap([16]u8, WaferLot),
    stage_durations_days: AutoHashMap(FabricationStage, i32),
    base_yield: f64,

    pub fn init(allocator: Allocator, process_node_nm: i32) !TSMCFabricationSimulator {
        var simulator = TSMCFabricationSimulator{
            .allocator = allocator,
            .process_node_nm = process_node_nm,
            .active_lots = AutoHashMap([16]u8, WaferLot).init(allocator),
            .completed_lots = AutoHashMap([16]u8, WaferLot).init(allocator),
            .stage_durations_days = AutoHashMap(FabricationStage, i32).init(allocator),
            .base_yield = 0.55,
        };

        try simulator.stage_durations_days.put(.design_received, 1);
        try simulator.stage_durations_days.put(.mask_generation, 14);
        try simulator.stage_durations_days.put(.wafer_start, 1);
        try simulator.stage_durations_days.put(.photolithography, 20);
        try simulator.stage_durations_days.put(.etching, 15);
        try simulator.stage_durations_days.put(.deposition, 10);
        try simulator.stage_durations_days.put(.chemical_mechanical_polishing, 8);
        try simulator.stage_durations_days.put(.metallization, 12);
        try simulator.stage_durations_days.put(.wafer_test, 5);
        try simulator.stage_durations_days.put(.dice, 2);
        try simulator.stage_durations_days.put(.packaging, 3);
        try simulator.stage_durations_days.put(.final_test, 4);
        try simulator.stage_durations_days.put(.shipped, 1);

        return simulator;
    }

    pub fn deinit(self: *TSMCFabricationSimulator) void {
        var active_it = self.active_lots.valueIterator();
        while (active_it.next()) |lot| {
            lot.deinit();
        }
        self.active_lots.deinit();

        var completed_it = self.completed_lots.valueIterator();
        while (completed_it.next()) |lot| {
            lot.deinit();
        }
        self.completed_lots.deinit();

        self.stage_durations_days.deinit();
    }

    pub fn submitLotForFabrication(self: *TSMCFabricationSimulator, design_id: [16]u8, quantity: i32) ![16]u8 {
        var prng = std.rand.DefaultPrng.init(blk: {
            var seed: u64 = undefined;
            std.os.getrandom(std.mem.asBytes(&seed)) catch 0;
            break :blk seed;
        });
        var lot_id: [16]u8 = undefined;
        prng.random().bytes(&lot_id);

        const current_time = @as(f64, @floatFromInt(std.time.timestamp()));
        const new_lot = try WaferLot.init(self.allocator, lot_id, design_id, quantity, current_time);

        try self.active_lots.put(lot_id, new_lot);
        return lot_id;
    }

    pub fn advanceFabricationProcess(self: *TSMCFabricationSimulator, lot_id: [16]u8) !bool {
        const lot_ptr = self.active_lots.getPtr(lot_id) orelse return false;

        const current_stage = lot_ptr.current_stage;
        if (current_stage == .shipped or current_stage == .failed) {
            return false;
        }

        const stages = [_]FabricationStage{
            .design_received,
            .mask_generation,
            .wafer_start,
            .photolithography,
            .etching,
            .deposition,
            .chemical_mechanical_polishing,
            .metallization,
            .wafer_test,
            .dice,
            .packaging,
            .final_test,
            .shipped,
            .failed,
        };

        var current_index: usize = 0;
        for (stages, 0..) |stage, idx| {
            if (stage == current_stage) {
                current_index = idx;
                break;
            }
        }

        if (current_index + 1 < stages.len) {
            lot_ptr.current_stage = stages[current_index + 1];

            const note = try std.fmt.allocPrint(self.allocator, "Advanced to stage at time {d}", .{@as(f64, @floatFromInt(std.time.timestamp()))});
            try lot_ptr.notes.append(note);

            if (lot_ptr.current_stage == .wafer_test) {
                try self.calculateYield(lot_ptr);
                if (lot_ptr.yield_rate < 0.1) {
                    lot_ptr.current_stage = .failed;
                    const fail_note = try std.fmt.allocPrint(self.allocator, "Lot failed due to critically low yield", .{});
                    try lot_ptr.notes.append(fail_note);
                    try self.finalizeLot(lot_id);
                    return true;
                }
            }

            if (lot_ptr.current_stage == .shipped) {
                try self.finalizeLot(lot_id);
            }
        }

        return true;
    }

    fn calculateYield(self: *TSMCFabricationSimulator, lot: *WaferLot) !void {
        var prng = std.rand.DefaultPrng.init(blk: {
            var seed: u64 = undefined;
            std.os.getrandom(std.mem.asBytes(&seed)) catch 0;
            break :blk seed;
        });

        const defect_density = prng.random().float(f64) * 1.4 + 0.1;
        const die_area_mm2: f64 = 100.0;
        const yield_factor = @exp(-defect_density * die_area_mm2);
        const process_variation = prng.random().float(f64) * 0.2 + 0.9;

        lot.yield_rate = self.base_yield * yield_factor * process_variation;
        lot.yield_rate = @max(0.0, @min(1.0, lot.yield_rate));

        const note = try std.fmt.allocPrint(self.allocator, "Yield calculated: {d:.2}", .{lot.yield_rate * 100.0});
        try lot.notes.append(note);
    }

    fn finalizeLot(self: *TSMCFabricationSimulator, lot_id: [16]u8) !void {
        if (self.active_lots.fetchRemove(lot_id)) |kv| {
            var lot = kv.value;
            lot.completion_time = @as(f64, @floatFromInt(std.time.timestamp()));
            try self.completed_lots.put(lot_id, lot);
        }
    }

    pub fn getLotStatus(self: *TSMCFabricationSimulator, lot_id: [16]u8) ?AutoHashMap([]const u8, []const u8) {
        const lot_ptr = self.active_lots.getPtr(lot_id) orelse self.completed_lots.getPtr(lot_id) orelse return null;

        var status = AutoHashMap([]const u8, []const u8).init(self.allocator);

        const stage_str = switch (lot_ptr.current_stage) {
            .design_received => "design_received",
            .mask_generation => "mask_generation",
            .wafer_start => "wafer_start",
            .photolithography => "photolithography",
            .etching => "etching",
            .deposition => "deposition",
            .chemical_mechanical_polishing => "chemical_mechanical_polishing",
            .metallization => "metallization",
            .wafer_test => "wafer_test",
            .dice => "dice",
            .packaging => "packaging",
            .final_test => "final_test",
            .shipped => "shipped",
            .failed => "failed",
        };
        status.put("current_stage", stage_str) catch {};

        return status;
    }

    pub fn runFullFabricationCycle(self: *TSMCFabricationSimulator, lot_id: [16]u8) !?AutoHashMap([]const u8, []const u8) {
        const lot_ptr = self.active_lots.getPtr(lot_id) orelse {
            return null;
        };

        while (lot_ptr.current_stage != .shipped and lot_ptr.current_stage != .failed) {
            _ = try self.advanceFabricationProcess(lot_id);
            std.time.sleep(10_000_000);
        }

        return self.getLotStatus(lot_id);
    }

    pub fn getShippedChips(self: *TSMCFabricationSimulator, lot_id: [16]u8) !ArrayList([16]u8) {
        var chips = ArrayList([16]u8).init(self.allocator);

        const lot = self.completed_lots.get(lot_id) orelse return chips;
        if (lot.current_stage != .shipped) {
            return chips;
        }

        const num_good_chips = @as(usize, @intFromFloat(@as(f64, @floatFromInt(lot.quantity)) * 25.0 * lot.yield_rate));

        var prng = std.rand.DefaultPrng.init(blk: {
            var seed: u64 = undefined;
            std.os.getrandom(std.mem.asBytes(&seed)) catch 0;
            break :blk seed;
        });

        var i: usize = 0;
        while (i < num_good_chips) : (i += 1) {
            var chip_id: [16]u8 = undefined;
            prng.random().bytes(&chip_id);
            try chips.append(chip_id);
        }

        return chips;
    }
};
