```zig
const std = @import("std");
const Allocator = std.mem.Allocator;
const ArrayList = std.ArrayList;
const AutoHashMap = std.AutoHashMap;

pub const FirmwareOpcode = enum(u8) {
    noop = 0x00,
    boot = 0x01,
    halt = 0x02,
    inject_event = 0x10,
    read_memory = 0x20,
    write_memory = 0x21,
    query_status = 0x30,
    reset_core = 0x40,
};

pub const FirmwareInstruction = struct {
    opcode: FirmwareOpcode,
    operand1: u32,
    operand2: u32,
    operand3: u32,
};

pub const FirmwareExecutor = struct {
    allocator: Allocator,
    instruction_queue: ArrayList(FirmwareInstruction),
    program_counter: usize,
    registers: [16]u32,
    memory: ArrayList(u8),

    pub fn init(allocator: Allocator) !FirmwareExecutor {
        return FirmwareExecutor{
            .allocator = allocator,
            .instruction_queue = ArrayList(FirmwareInstruction).init(allocator),
            .program_counter = 0,
            .registers = [_]u32{0} ** 16,
            .memory = ArrayList(u8).init(allocator),
        };
    }

    pub fn deinit(self: *FirmwareExecutor) void {
        self.instruction_queue.deinit();
        self.memory.deinit();
    }

    pub fn loadProgram(self: *FirmwareExecutor, instructions: []const FirmwareInstruction) !void {
        for (instructions) |instr| {
            try self.instruction_queue.append(instr);
        }
    }

    pub fn execute(self: *FirmwareExecutor) !void {
        while (self.program_counter < self.instruction_queue.items.len) {
            const instr = self.instruction_queue.items[self.program_counter];

            switch (instr.opcode) {
                .noop => {},
                .boot => {
                    self.registers[0] = 1;
                },
                .halt => {
                    return;
                },
                .inject_event => {
                    self.registers[1] = instr.operand1;
                },
                .read_memory => {
                    if (instr.operand1 < self.memory.items.len) {
                        self.registers[2] = self.memory.items[instr.operand1];
                    }
                },
                .write_memory => {
                    if (instr.operand1 < self.memory.items.len) {
                        self.memory.items[instr.operand1] = @intCast(instr.operand2 & 0xFF);
                    }
                },
                .query_status => {
                    self.registers[3] = self.program_counter;
                },
                .reset_core => {
                    for (&self.registers) |*reg| {
                        reg.* = 0;
                    }
                },
            }

            self.program_counter += 1;
        }
    }

    pub fn reset(self: *FirmwareExecutor) void {
        self.program_counter = 0;
        for (&self.registers) |*reg| {
            reg.* = 0;
        }
    }
};
